func:
// From HA state-change (or outputInitially seed) to the watch's retained state topic.
// WIRE = HA-native strings: crates/climate-model parses mode/action/modes as strings
// (HvacMode::from_ha) and maps to its own int enum for the UI. Do NOT pre-int-encode here.
const s = (msg.data && msg.data.new_state) ? msg.data.new_state
        : (msg.payload && msg.payload.entity_id) ? msg.payload : null;
if (!s || !s.entity_id || s.entity_id.indexOf('climate.') !== 0) return null;
const a = s.attributes || {};
const oid = s.entity_id.slice('climate.'.length);
// cache this device's RAW HA hvac_modes so the command node can translate auto<->heat_cool
flow.set('hamodes:' + oid, a.hvac_modes || []);
const out = {
  name:   a.friendly_name || oid,
  cur:    (a.current_temperature ?? null),
  set:    (a.temperature ?? null),
  mode:   s.state,                          // HA hvac_mode string: off|heat|cool|auto|heat_cool|dry|fan_only
  action: (a.hvac_action || 'idle'),        // HA hvac_action string: idle|heating|cooling|drying|fan|off
  min:    (a.min_temp ?? 45),
  max:    (a.max_temp ?? 95),
  step:   (a.target_temp_step ?? 1.0),
  modes:  (a.hvac_modes || [])              // array of HA mode strings the device supports
};
return {
  topic: 'watch/climate/' + oid + '/state',
  payload: JSON.stringify(out),
  qos: 0,
  retain: true
};

// oracle-t9 A4: publish the SET of climate object_ids as ONE retained roster the
// watch can read without waiting on every per-entity state topic. Informational
// in v1 (the watch/climate/+/state wildcard stays authoritative for rendering).
// Fed off the same state-change stream; outputInitially seeds it at deploy.
const s = (msg.data && msg.data.new_state) ? msg.data.new_state
        : (msg.payload && msg.payload.entity_id) ? msg.payload : null;
if (!s || !s.entity_id || s.entity_id.indexOf('climate.') !== 0) return null;
const set = flow.get('roster') || {};
set[s.entity_id.slice('climate.'.length)] = true;
flow.set('roster', set);
// Kept bounded (<=10 ids) — the watch treats a >~200 B roster as a protocol
// error, and state topics remain authoritative, so truncation is harmless.
const bounded = Object.keys(set).sort().slice(0, 10);
return { topic: 'watch/climate/roster', payload: JSON.stringify(bounded), qos: 0, retain: true };

// topic: watch/climate/<oid>/set ; payload {"set":72} or {"mode":"heat"} (watch sends HA strings)
const parts = (msg.topic || '').split('/');
const oid = parts[2];
if (!oid) return null;
let p;
try { p = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload; }
catch (e) { node.warn('bad climate cmd payload: ' + msg.payload); return null; }
const entity_id = 'climate.' + oid;
const modeNames = ['off','heat','cool','auto','fan_only','dry'];
if (p && p.set !== undefined && p.set !== null) {
  const t = Number(p.set);
  if (!isFinite(t)) return null;
  msg.payload = { domain:'climate', service:'set_temperature', target:{ entity_id }, data:{ temperature: t } };
  return msg;
}
if (p && p.mode !== undefined && p.mode !== null) {
  let hm = (typeof p.mode === 'number') ? modeNames[p.mode] : String(p.mode);
  if (!hm) return null;
  // The watch folds heat_cool<->auto to one UI mode; translate to whatever THIS device supports
  // (Nest = heat_cool-only, minisplits = auto). hamodes cached by the state node.
  const supported = flow.get('hamodes:' + oid) || [];
  if (hm === 'auto' && supported.indexOf('auto') === -1 && supported.indexOf('heat_cool') !== -1) hm = 'heat_cool';
  else if (hm === 'heat_cool' && supported.indexOf('heat_cool') === -1 && supported.indexOf('auto') !== -1) hm = 'auto';
  if (supported.length && supported.indexOf(hm) === -1) { node.warn('climate ' + oid + ': mode ' + hm + ' unsupported'); return null; }
  msg.payload = { domain:'climate', service:'set_hvac_mode', target:{ entity_id }, data:{ hvac_mode: hm } };
  return msg;
}
return null;
